CREATE TABLE a16_saldo(id NUMBER PRIMARY KEY,valor NUMBER NOT NULL CHECK(valor>=0));
INSERT INTO a16_saldo VALUES(1,5);
COMMIT;
CREATE OR REPLACE PROCEDURE a16_consumir(p_id IN NUMBER,p_qtd IN NUMBER,p_restante OUT NUMBER)
AUTHID DEFINER IS
BEGIN
 IF p_qtd IS NULL OR p_qtd<=0 THEN RAISE_APPLICATION_ERROR(-20001,'Quantidade invalida'); END IF;
 UPDATE a16_saldo SET valor=valor-p_qtd
 WHERE id=p_id AND valor>=p_qtd RETURNING valor INTO p_restante;
 IF SQL%ROWCOUNT=0 THEN RAISE_APPLICATION_ERROR(-20002,'Saldo insuficiente ou ID ausente'); END IF;
END;
/
DECLARE v_n NUMBER; BEGIN a16_consumir(p_id=>1,p_qtd=>2,p_restante=>v_n); DBMS_OUTPUT.PUT_LINE('restante='||v_n); END;
/
ROLLBACK;

