CREATE OR REPLACE PACKAGE a17_preco AUTHID DEFINER AS
 FUNCTION total(p_horas NUMBER,p_valor_hora NUMBER) RETURN NUMBER;
END a17_preco;
/
CREATE OR REPLACE PACKAGE BODY a17_preco AS
 FUNCTION total(p_horas NUMBER,p_valor_hora NUMBER) RETURN NUMBER IS
 BEGIN
  IF p_horas IS NULL OR p_valor_hora IS NULL OR p_horas<=0 OR p_valor_hora<0 THEN
   RAISE_APPLICATION_ERROR(-20001,'Entrada invalida');
  END IF;
  RETURN p_horas*p_valor_hora;
 END total;
END a17_preco;
/
BEGIN DBMS_OUTPUT.PUT_LINE('total='||a17_preco.total(3,10)); END;
/

