CREATE TABLE a35_lote(id NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,qtd NUMBER NOT NULL CHECK(qtd>0));
DECLARE
 TYPE numeros IS TABLE OF NUMBER;
 v numeros:=numeros(2,-1,3);
 e_lote EXCEPTION;
 PRAGMA EXCEPTION_INIT(e_lote,-24381);
BEGIN
 BEGIN
  FORALL i IN 1..v.COUNT SAVE EXCEPTIONS
   INSERT INTO a35_lote(qtd) VALUES(v(i));
 EXCEPTION WHEN e_lote THEN
  FOR j IN 1..SQL%BULK_EXCEPTIONS.COUNT LOOP
   DBMS_OUTPUT.PUT_LINE('indice='||SQL%BULK_EXCEPTIONS(j).ERROR_INDEX||
    ' codigo='||SQL%BULK_EXCEPTIONS(j).ERROR_CODE);
  END LOOP;
 END;
END;
/
SELECT qtd FROM a35_lote ORDER BY qtd;
ROLLBACK;
SELECT COUNT(*) AS persistidas FROM a35_lote;

