CREATE TABLE a36_recurso(id NUMBER PRIMARY KEY,vagas NUMBER NOT NULL CHECK(vagas>=0));
CREATE TABLE a36_reserva(req VARCHAR2(40) PRIMARY KEY,recurso_id NUMBER NOT NULL REFERENCES a36_recurso(id),
 qtd NUMBER NOT NULL CHECK(qtd>0));
INSERT INTO a36_recurso VALUES(1,2);
COMMIT;
CREATE OR REPLACE PROCEDURE a36_reservar(p_req VARCHAR2,p_recurso NUMBER,p_qtd NUMBER)
AUTHID DEFINER IS
BEGIN
 IF p_req IS NULL OR p_qtd IS NULL OR p_qtd<=0 THEN RAISE_APPLICATION_ERROR(-20001,'Entrada invalida'); END IF;
 SAVEPOINT a36_inicio;
 BEGIN
  INSERT INTO a36_reserva(req,recurso_id,qtd) VALUES(p_req,p_recurso,p_qtd);
  UPDATE a36_recurso SET vagas=vagas-p_qtd WHERE id=p_recurso AND vagas>=p_qtd;
  IF SQL%ROWCOUNT=0 THEN RAISE_APPLICATION_ERROR(-20002,'Sem vagas'); END IF;
 EXCEPTION WHEN OTHERS THEN
  ROLLBACK TO a36_inicio;
  RAISE;
 END;
END;
/
BEGIN a36_reservar('req-1',1,1); END;
/
SELECT id,vagas FROM a36_recurso ORDER BY id;
SELECT req,recurso_id,qtd FROM a36_reserva ORDER BY req;
ROLLBACK;
